{
  "id": "V050",
  "checks": [
    {
      "field": "purpose",
      "score": 2,
      "reason": "영어 독자가 이해할 수 있는 기업 소식 번역이라는 목적이 보존됨."
    },
    {
      "field": "action",
      "score": 2,
      "reason": "한국어 기사를 영어로 번역하고 원문과 비교해 검토하는 흐름이 보존됨."
    },
    {
      "field": "object",
      "score": 2,
      "reason": "국내에서 작성한 기업 소식 기사가 보존됨."
    },
    {
      "field": "input",
      "score": 2,
      "reason": "한국어로 작성된 국내 기업 소식 기사가 명시됨."
    },
    {
      "field": "output",
      "score": 2,
      "reason": "영어 독자가 이해할 수 있는 영어 번역문이 명시됨."
    },
    {
      "field": "constraints",
      "score": 2,
      "reason": "원문에 없는 인용이나 성과를 추가하지 않는 제약과 게시 결정 권한이 보존됨."
    },
    {
      "field": "no_added_functions",
      "score": 2,
      "reason": "뷰에서 원문 대조 검토, 누락 확인, 게시 결정은 원문에 근거하며 새로운 기능은 추가되지 않음."
    },
    {
      "field": "roles",
      "score": 2,
      "reason": "해외 배포 담당자의 번역·확인과 편집자의 검토·게시 결정 역할이 보존됨."
    }
  ],
  "issues": [],
  "permission_interpretation": "게시 결정은 편집자의 권한으로 제시되며, 번역 담당자나 시스템이 게시를 결정한다고 주장하지 않음."
}
